<script setup lang="ts">
import{ref,watch}from'vue';import{useSalesScope}from'./use-sales-scope';import{receiptPendingTarget,validClinicalReceiptStatus}from'./clinical-receipt-status';
const props=defineProps<{staff:any;pending:any;busy:boolean}>(),emit=defineEmits(['clear','retry']),status=ref<any>(null),checking=ref(false),checked=ref(false),error=ref(''),scope=useSalesScope(()=>JSON.stringify([props.staff.accountId,props.staff.employeeId,props.pending]));
watch(()=>JSON.stringify([props.staff.accountId,props.staff.employeeId,props.pending]),()=>{status.value=null;checking.value=false;checked.value=false;error.value='';},{flush:'sync'});
async function verify(){if(props.busy||checking.value||props.pending?.known)return;const current=scope.begin('status');checking.value=true;error.value='';status.value=null;checked.value=false;const c=new AbortController(),timer=setTimeout(()=>c.abort(),15000);try{const t=receiptPendingTarget(props.pending),r=await fetch('/api/v1/clinical/receipt-commands/'+t.requestId+'?'+new URLSearchParams({visitId:t.visitId}),{credentials:'same-origin',signal:c.signal}),v=await r.json();if(!current())return;if(!r.ok)throw Error(v.message||'原收款核实失败。');status.value=validClinicalReceiptStatus(props.pending,v);}catch(e:any){if(current())error.value=e.message;}finally{clearTimeout(timer);if(current.active())checking.value=false;}}
function clear(){if(!props.busy&&!checking.value&&(props.pending?.known||status.value?.state==='completed'))emit('clear',props.pending);}
function retry(){if(!props.busy&&!checking.value&&checked.value&&status.value?.state==='not_found'&&!props.pending?.known){validClinicalReceiptStatus(props.pending,status.value);status.value=null;checked.value=false;emit('retry',props.pending);}}
</script>
<template><section class="b-alert warning"><template v-if="pending.known"><p>已核对原收款保存{{pending.phase==='rejected'?'被拒绝':'成功'}}，只需清理本机提示。</p><button class="b-button outline" :disabled="busy" @click="clear">仅清理本机提示</button></template><template v-else><p>收款保存结果待核实，请先只读查询原请求。</p><button class="b-button outline" :disabled="busy||checking" @click="verify">{{checking?'正在核实…':'只读核实原收款提交'}}</button><p v-if="error" role="alert">{{error}}</p><template v-if="status?.state==='completed'"><p>已查到原收款第{{status.version}}版，保存于{{new Date(status.completedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}。</p><button class="b-button outline" :disabled="busy||checking" @click="clear">已核对，清理本机提示</button></template><template v-else-if="status?.state==='not_found'"><p>暂未见成功凭据，可能仍在处理、未提交或已回滚，不能认定未保存。</p><label><input type="checkbox" v-model="checked" :disabled="busy||checking"/>已核对，沿原请求号和原内容重试</label><button class="b-button outline" :disabled="busy||checking||!checked" @click="retry">重试原收款保存</button></template></template></section></template>
<style scoped>.b-alert{display:block}.b-alert p{margin:10px 0;line-height:1.8}.b-alert label{display:flex;align-items:center;gap:10px;margin:14px 0;line-height:1.7}.b-alert input[type=checkbox]{width:18px;height:18px;flex:0 0 18px}.b-alert button{margin:6px 0}</style>
